<script setup lang="ts">
import { computed,ref } from 'vue'
import type { Editor } from '../lib/editor'
import { isContainer } from '../lib/widgets'
import type { Widget } from '../lib/model'
const props=defineProps<{editor:Editor}>(),emit=defineEmits<{context:[event:MouseEvent,id:string]}>()
const rows=computed(()=>{const result:{widget:Widget;depth:number}[]=[],seen=new Set<string>();function visit(parentId:string|undefined,depth:number){for(const widget of props.editor.page.value.widgets.filter(widget=>(widget.parentId??undefined)===parentId)){if(seen.has(widget.id))continue;seen.add(widget.id);result.push({widget,depth});visit(widget.id,depth+1)}}visit(undefined,0);for(const widget of props.editor.page.value.widgets)if(!seen.has(widget.id))result.push({widget,depth:0});return result})
function select(event:MouseEvent,id:string){let current=props.editor.page.value.widgets.find(widget=>widget.id===id);while(current?.parentId){const parent=props.editor.page.value.widgets.find(widget=>widget.id===current?.parentId);if(!parent)break;if(parent.kind==='tabs'||parent.kind==='stack')props.editor.activeSlots.value[parent.id]=current.slotId??parent.slots?.[0]?.id??'content';current=parent}if(event.shiftKey||event.ctrlKey||event.metaKey)props.editor.selected.value=props.editor.selected.value.includes(id)?props.editor.selected.value.filter(value=>value!==id):[...props.editor.selected.value,id];else props.editor.selected.value=[id]}
function toggle(id:string,key:'hidden'|'locked'){props.editor.mutate(()=>{const widget=props.editor.page.value.widgets.find(widget=>widget.id===id);if(widget)widget.editor={...widget.editor,[key]:!widget.editor?.[key]}})}

const dragging=ref(''),dropTarget=ref('')
function dragStart(event:DragEvent,id:string){dragging.value=id;event.dataTransfer?.setData('application/hmi-tree-widget',id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function over(event:DragEvent,id:string){if(!dragging.value||dragging.value===id||props.editor.descendants([dragging.value]).some(widget=>widget.id===id))return;event.preventDefault();dropTarget.value=id}
function drop(event:DragEvent,targetId?:string){event.preventDefault();event.stopPropagation();const id=dragging.value||event.dataTransfer?.getData('application/hmi-tree-widget'),source=props.editor.page.value.widgets.find(widget=>widget.id===id),target=props.editor.page.value.widgets.find(widget=>widget.id===targetId);dragging.value='';dropTarget.value='';if(!source||source.editor?.locked||source===target||target&&props.editor.descendants([source.id]).some(widget=>widget.id===target.id))return;const parentId=target&&isContainer(target)?target.id:target?.parentId??undefined,slotId=target&&isContainer(target)?props.editor.activeSlots.value[target.id]??target.slots?.[0]?.id??'content':target?.slotId;const board=document.querySelector<HTMLElement>('.design-board'),element=board?.querySelector<HTMLElement>(`[data-widget-id="${source.id}"]`),content=parentId?board?.querySelector<HTMLElement>(`[data-container-content="${parentId}"][data-slot-id="${slotId}"]`):board;const oldRect=element?.getBoundingClientRect(),rect=content?.getBoundingClientRect(),scale=board?board.getBoundingClientRect().width/props.editor.project.value.width:1;props.editor.mutate(()=>{source.parentId=parentId;source.slotId=slotId;if(oldRect&&rect){source.x=Math.max(0,(oldRect.left-rect.left)/scale+(content?.scrollLeft??0));source.y=Math.max(0,(oldRect.top-rect.top)/scale+(content?.scrollTop??0))}const list=props.editor.page.value.widgets;list.splice(list.indexOf(source),1);const index=target&&!isContainer(target)?list.indexOf(target)+1:list.length;list.splice(index,0,source)});props.editor.selected.value=[source.id]}

</script>
<template><div class="object-tree" role="tree" @dragover.prevent @drop="drop($event)"><div v-for="{widget,depth} in rows" :key="widget.id" class="object-tree-row" :class="{selected:editor.selected.value.includes(widget.id),hidden:widget.editor?.hidden,'drop-target':dropTarget===widget.id}" role="treeitem" :draggable="!widget.editor?.locked" @dragstart="dragStart($event,widget.id)" @dragover.stop="over($event,widget.id)" @dragleave="dropTarget=''" @drop="drop($event,widget.id)" :aria-selected="editor.selected.value.includes(widget.id)" :style="{paddingLeft:`${8+depth*15}px`}" @click="select($event,widget.id)" @contextmenu.prevent="emit('context',$event,widget.id)"><span>{{ widget.parentId?'└':'◇' }}</span><span class="object-name" data-project-text>{{ widget.name }}</span><button :title="widget.editor?.hidden?'显示':'隐藏'" @click.stop="toggle(widget.id,'hidden')">{{ widget.editor?.hidden?'◌':'◉' }}</button><button :title="widget.editor?.locked?'解锁':'锁定'" @click.stop="toggle(widget.id,'locked')">{{ widget.editor?.locked?'🔒':'⌑' }}</button></div></div></template>
<style scoped>.object-tree{font-size:12px;overflow:auto;min-height:0}.object-tree-row{display:flex;gap:6px;align-items:center;min-height:33px;cursor:pointer;border-radius:4px}.object-tree-row:hover{background:#f1f5f9}.object-tree-row.selected{background:#e9f3ff;color:#0f6cbd}.object-name{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.object-tree-row button{font-size:11px;padding:5px;opacity:.6}.object-tree-row.hidden .object-name{opacity:.5;text-decoration:line-through}.object-tree-row.drop-target{outline:2px solid #0f6cbd;background:#e9f3ff}</style>
